<script>
import { adminApi } from "../../services/adminApi";
export default { data(){return {loading:true,error:"",items:[]}}, async mounted(){try{this.items=await adminApi.get("contractors")}catch(e){this.error=e.response?.data?.message||"Não foi possível carregar os dados."}finally{this.loading=false}}, methods:{money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})},date(v){return v?new Date(v).toLocaleDateString("pt-BR"):"—"}}}
</script><template><div><h4>Contratantes</h4><p class="text-muted">Clientes compradores de shows cadastrados na plataforma.</p><div class="card"><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Nome</th><th>E-mail</th><th>Celular</th><th>Cadastro</th><th>Shows</th></tr></thead><tbody><tr v-for="x in items" :key="x.id"><td><strong>{{x.nomeCompleto}}</strong></td><td>{{x.email}}</td><td>{{x.celular}}</td><td>{{date(x.createdAt)}}</td><td>{{x.shows}}</td></tr></tbody></table><div v-if="error" class="alert alert-danger">{{error}}</div></div></div></div></template>